<?php
require_once __DIR__.'/../app.php';require_once __DIR__.'/../ui.php';require_once __DIR__.'/../report_service.php';require_once __DIR__.'/../csv.php';require_staff();$report=null;
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    verify_csrf();$action=request_string($_POST,'action');
    try{
        if($action==='generate'){
            $type=request_string($_POST,'report_type');$filters=[];foreach(['q','student_id','offering_id','course_id','year_level','section_id','subject_id','faculty_id','school_year_id','term_id','workflow','status','from','to','role','is_active','action_type','entity','intervention_status','gwa_policy_id']as $key)$filters[$key]=request_string($_POST,$key);
            $filters['action']=$filters['action_type'];$report=build_report($type,$filters);$token=bin2hex(random_bytes(16));$_SESSION['reports']??=[];$_SESSION['reports'][$token]=['type'=>$type,'filters'=>$filters,'created'=>time()];if(count($_SESSION['reports'])>10)array_shift($_SESSION['reports']);
            audit('report_generate','reports',null,'Generated '.$report['title'],null,['filters'=>$filters,'rows'=>count($report['data'])]);redirect('reports.php?report='.$token);
        }elseif($action==='export'){
            $saved=$_SESSION['reports'][request_string($_POST,'report')]??null;if(!$saved||time()-$saved['created']>1800)throw new DomainException('Report expired. Generate it again.');$report=build_report($saved['type'],$saved['filters']);audit('report_export','reports',null,'Exported '.$report['title'],null,['filters'=>$saved['filters'],'rows'=>count($report['data'])]);output_csv('student-grade-report-'.date('Ymd-His').'.csv',$report['data'],$report['columns']);
        }else throw new DomainException('Unknown report action.');
    }catch(DomainException $e){flash('danger',$e->getMessage());}
}
$token=request_string($_GET,'report');if($token!==''){$saved=$_SESSION['reports'][$token]??null;if(!$saved||time()-$saved['created']>1800)throw new DomainException('Report expired. Generate it again.');$report=build_report($saved['type'],$saved['filters']);}
page_start('Reports','Generate an authorized, auditable report, then preview, print, save as PDF, or export CSV.');
?><details class="panel no-print" <?=$report?'':'open'?>><summary>Report builder</summary><form method="post" class="filter-grid mt-3"><?php csrf_field();$types=report_types();if(!is_admin())unset($types['users'],$types['activity']);select_field('report_type','Report type',$types,'performance');grade_filter_form(['workflow'=>'Published']);select_field('gwa_policy_id','GWA interpretation policy',choices('grading_policies'),setting('gwa_policy_id','1'));if(is_admin()){select_field('role','Account role',['Administrator'=>'Administrator','Faculty'=>'Faculty'],'',false);select_field('is_active','Account status',[1=>'Active',0=>'Inactive'],'',false);}input_field('action_type','Audit transaction type (exact, optional)','','text',false);input_field('entity','Audit category (optional)','','text',false);select_field('intervention_status','Intervention status',['Open'=>'Open','In Progress'=>'In Progress','Resolved'=>'Resolved'],'',false);?><div class="field align-self-end"><button class="btn btn-primary" name="action" value="generate">Generate report</button></div><p class="wide text-secondary">Grade dates filter entry dates; activity dates filter action dates; intervention dates filter follow-up dates. Official academic reports use Published results. Other workflow selections produce a working report.</p></form></details>
<?php if($report):?><section class="panel report-document"><div class="report-toolbar no-print"><button class="btn btn-primary" type="button" onclick="window.print()">Print preview / Save as PDF</button><form method="post"><?php csrf_field();?><input type="hidden" name="report" value="<?=h($token)?>"><button class="btn btn-outline-primary" name="action" value="export">Export CSV</button></form></div><header class="report-header"><img src="<?=h(school_logo())?>" alt="School logo" width="68" height="68"><div><h2><?=h(setting('school_name'))?></h2><p><?=h(setting('campus'))?></p><p><?=h(setting('report_header'))?></p></div></header><h2><?=h($report['title'])?></h2><p class="report-label"><?=$report['official']?'PUBLISHED ACADEMIC RESULTS — system-generated; subject to school certification':'WORKING / ADMINISTRATIVE REPORT — may include unpublished results'?></p><p>Generated <?=h($report['generated_at'])?> · Prepared by <?=h($report['prepared_by'])?></p><p class="small">Filters: <?php echo h(readable_report_filters($report['filters']));?></p><?php foreach($report['summary']as $key=>$value)echo '<p><strong>'.h($key).':</strong> '.h($value).'</p>';data_table($report['data'],$report['columns']);?><div class="report-signatures"><p>Prepared by: ____________________</p><p>Reviewed / approved by: ____________________</p></div></section><?php endif;page_end();
